479	const args: string[] = process.argv.slice(2);
480	const help: string = `QuillPress - 内容编辑与刊物发布
481	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
482	       node server.ts --help
483	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
484	Port 0 selects an available port.
