487	  process.stdout.write(help);
488	  process.exit(args.length === 0 ? 2 : 0);
489	}
490	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
491	let host: string = '127.0.0.1';
492	let port: number = 8080;
493	let dataDir: string = 'data';
494	while (args.length) {
495	  const flag = args.shift();
496	  const value = args.shift();
497	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
498	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
499	  }
500	  if (flag === '--host') host = value;
501	  else if (flag === '--port') {
502	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
503	    port = Number(value);
504	  } else dataDir = value;
505	}
506	mkdirSync(dataDir, { recursive: true });
507	const dataFile = join(dataDir, 'articles.json');
508	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
509	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
