512	interface Article {
513	  id: string;
514	  title: string;
515	  summary: string;
516	  body: string;
517	  status: 'draft';
518	  createdAt: string;
519	  version: number;
520	}
521	interface StoredArticle {
522	  id?: unknown;
523	  title?: unknown;
524	  summary?: unknown;
525	  body?: unknown;
526	  status?: unknown;
527	  createdAt?: unknown;
528	  version?: unknown;
529	}
530	interface DraftInput {
531	  title: string;
532	  summary: string;
533	  body: string;
534	}
