545	function respond(res: ServerResponse, status: number, value: unknown, html = false): void {
546	  const body = html ? String(value) : JSON.stringify(value);
547	  res.writeHead(status, {
548	    'content-type': html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
549	    'content-length': Buffer.byteLength(body),
550	  });
551	  res.end(body);
