564	// Normalize a stored record. Drafts saved by older versions have no `version`
565	// field; those are treated as version 0 and can be opened and edited directly.
566	function normalizeArticle(record: unknown): Article | null {
567	  if (typeof record !== 'object' || record === null || Array.isArray(record)) return null;
568	  const r = record as StoredArticle;
569	  if (typeof r.id !== 'string' || typeof r.title !== 'string' || typeof r.body !== 'string') return null;
570	  if (r.status !== 'draft' || typeof r.createdAt !== 'string') return null;
571	  const version = typeof r.version === 'number' && Number.isInteger(r.version) && r.version >= 0 ? r.version : 0;
572	  return {
573	    id: r.id,
574	    title: r.title,
575	    summary: typeof r.summary === 'string' ? r.summary : '',
576	    body: r.body,
577	    status: 'draft',
578	    createdAt: r.createdAt,
579	    version,
580	  };
581	}
