618	function readBody(req: IncomingMessage): Promise<string> {
619	  return new Promise((resolve, reject) => {
620	    const chunks: Buffer[] = [];
621	    let size = 0;
622	    let settled = false;
623	    req.on('data', (chunk: unknown) => {
624	      if (settled) return;
625	      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
626	      size += buf.length;
627	      if (size > MAX_BODY_BYTES) {
628	        settled = true;
629	        reject(new HttpError(400, 'request body is too large'));
630	        req.destroy();
631	        return;
632	      }
633	      chunks.push(buf);
634	    });
635	    req.on('end', () => {
636	      if (!settled) resolve(Buffer.concat(chunks).toString('utf8'));
637	    });
638	    req.on('error', (error: Error) => {
639	      if (!settled) reject(new HttpError(400, `could not read request body: ${error.message}`));
640	    });
641	  });
642	}
643	
644	function parseJsonObject(text: string): Record<string, unknown> {
645	  let payload: unknown;
646	  try {
647	    payload = JSON.parse(text);
648	  } catch (error) {
649	    throw new HttpError(400, `invalid JSON: ${(error as Error).message}`);
650	  }
651	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
652	    throw new HttpError(400, 'request body must be a JSON object');
653	  }
654	  return payload as Record<string, unknown>;
655	}
656	
657	function validateDraftInput(data: Record<string, unknown>): DraftInput {
658	  if (typeof data.title !== 'string') {
659	    throw new HttpError(400, 'title must be a string');
660	  }
661	  const title = data.title.trim();
662	  if (title.length === 0) {
663	    throw new HttpError(400, 'title must not be empty or only whitespace');
664	  }
665	  let summary = '';
666	  if (Object.prototype.hasOwnProperty.call(data, 'summary')) {
667	    if (typeof data.summary !== 'string') throw new HttpError(400, 'summary must be a string when provided');
668	    summary = data.summary;
669	  }
670	  if (typeof data.body !== 'string') {
671	    throw new HttpError(400, 'body must be a string');
672	  }
673	  return { title, summary, body: data.body };
674	}
675	
676	// Updates carry the version the editor loaded; stale versions are rejected.
677	// As with creation, summary may be omitted (saved as empty string) but a
678	// present non-string summary is a 400.
679	function validateUpdateInput(data: Record<string, unknown>): DraftInput & { version: number } {
680	  const fields = validateDraftInput(data);
681	  if (typeof data.version !== 'number' || !Number.isInteger(data.version) || data.version < 0) {
682	    throw new HttpError(400, 'version must be a non-negative integer');
683	  }
684	  return { ...fields, version: data.version };
685	}
