687	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
688	  let route: string;
689	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; }
690	  catch { respond(res, 400, { error: 'invalid request path' }); return; }
691	
692	  // /api/articles/:id (match the raw path first; decode only the captured id)
693	  const itemMatch = /^\/api\/articles\/([^/]+)$/.exec(route);
694	  let itemId: string | null = null;
695	  if (itemMatch) {
696	    try { itemId = decodeURIComponent(itemMatch[1]); }
697	    catch { respond(res, 400, { error: 'invalid article id encoding' }); return; }
698	  }
699	
700	  if (!['/', '/health', '/api/articles'].includes(route) && !itemMatch) {
701	    respond(res, 404, { error: 'not found' });
702	    return;
703	  }
704	
705	  if (route === '/') {
706	    if (req.method === 'GET') { respond(res, 200, PAGE, true); return; }
707	    methodNotAllowed(res, 'GET');
708	    return;
709	  }
710	  if (route === '/health') {
711	    if (req.method === 'GET') { respond(res, 200, { status: 'ok', product: PRODUCT }); return; }
712	    methodNotAllowed(res, 'GET');
713	    return;
714	  }
715	
716	  if (itemMatch && itemId !== null) {
717	    const id = itemId;
718	    if (req.method === 'GET') {
719	      const articles = readArticles();
720	      const article = articles.find((a) => a.id === id);
721	      if (!article) throw new HttpError(404, 'article not found');
722	      respond(res, 200, { article });
723	      return;
724	    }
725	    if (req.method === 'PUT') {
726	      const text = await readBody(req);
727	      const data = parseJsonObject(text);
728	      const fields = validateUpdateInput(data);
729	      const result = await enqueueWrite((): { status: number; article: Article } => {
730	        const records = readArticles();
731	        const index = records.findIndex((a) => a.id === id);
732	        if (index === -1) {
733	          throw new HttpError(404, 'article not found');
734	        }
735	        const current = records[index];
736	        if (fields.version !== current.version) {
737	          // 409 carries the currently saved article for side-by-side comparison.
738	          const conflict = new HttpError(409, 'a newer version of this article has been saved');
739	          (conflict as HttpError & { article?: Article }).article = current;
740	          throw conflict;
741	        }
742	        const updated: Article = {
743	          id: current.id,
744	          title: fields.title,
745	          summary: fields.summary,
746	          body: fields.body,
747	          status: current.status,
748	          createdAt: current.createdAt,
749	          version: current.version + 1,
750	        };
751	        records[index] = updated;
752	        writeArticles(records);
753	        return { status: 200, article: updated };
754	      });
755	      respond(res, result.status, { article: result.article });
756	      return;
757	    }
758	    methodNotAllowed(res, 'GET, PUT');
759	    return;
760	  }
761	
762	  // /api/articles
763	  if (req.method === 'GET') {
764	    respond(res, 200, { [RESOURCE]: readArticles() });
765	    return;
766	  }
767	  if (req.method === 'POST') {
768	    const text = await readBody(req);
769	    const data = parseJsonObject(text);
770	    const fields = validateDraftInput(data);
771	    const article: Article = {
772	      id: randomUUID(),
773	      title: fields.title,
774	      summary: fields.summary,
775	      body: fields.body,
776	      status: 'draft',
777	      createdAt: new Date().toISOString(),
778	      version: 1,
779	    };
780	    await enqueueWrite((): void => {
781	      const records = readArticles();
782	      records.push(article);
783	      writeArticles(records);
784	    });
785	    respond(res, 201, { article });
786	    return;
787	  }
788	  methodNotAllowed(res, 'GET, POST');
789	}
790	
791	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
792	  handle(req, res).catch((error: unknown) => {
793	    if (res.writableEnded) return;
794	    if (error instanceof HttpError) {
795	      const payload: { error: string; article?: Article } = { error: error.message };
796	      const withArticle = error as HttpError & { article?: Article };
797	      if (error.status === 409 && withArticle.article) payload.article = withArticle.article;
798	      respond(res, error.status, payload);
799	      return;
800	    }
801	    respond(res, 500, { error: error instanceof Error ? error.message : 'internal error' });
802	  });
803	});
804	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
