const vm = require('node:vm');
const { setTimeout: st } = require('node:timers/promises');

const BASE = 'http://127.0.0.1:8123';

class El {
  constructor(tag, id) {
    this.tagName = tag;
    this.id = id || '';
    this.children = [];
    this.value = '';
    this.textContent = '';
    this.className = '';
    this.type = '';
    this.disabled = false;
    this.hidden = false;
    this._listeners = {};
    this.classList = {
      _set: new Set(),
      add(c) { this._set.add(c); },
      remove(c) { this._set.delete(c); },
      contains(c) { return this._set.has(c); },
    };
  }
  appendChild(c) { this.children.push(c); return c; }
  addEventListener(type, fn) {
    (this._listeners[type] = this._listeners[type] || []).push(fn);
  }
  dispatch(type, ev) { (this._listeners[type] || []).forEach((fn) => fn(ev)); }
  click() { this.dispatch('click', {}); }
  focus() {}
  reset() {}
  set innerHTML(v) { if (v === '') this.children = []; }
  get innerHTML() { return ''; }
  querySelector() { return null; }
  // find first descendant by tag (and optional text)
  find(tag, text) {
    for (const c of this.children) {
      if ((!tag || c.tagName === tag) && (text === undefined || c.textContent === text)) return c;
      const d = c.find(tag, text);
      if (d) return d;
    }
    return null;
  }
  findAll(tag, out = []) {
    for (const c of this.children) {
      if (!tag || c.tagName === tag) out.push(c);
      c.findAll(tag, out);
    }
    return out;
  }
}

const ids = {};
['draft-form','title','summary','body','save-btn','cancel-btn','status','edit-banner',
 'conflict-box','article-list','empty-tip'].forEach((id) => { ids[id] = new El(id === 'draft-form' ? 'form' : 'div', id); });
const documentStub = {
  getElementById: (id) => ids[id] || (ids[id] = new El('div', id)),
  createElement: (tag) => new El(tag),
};

// Slow down PUT responses so we can reliably edit while a save is in flight.
const realFetch = fetch;
let putInFlight = 0;
const slowFetch = (url, opts) => {
  const p = realFetch(url, opts);
  if (opts && opts.method === 'PUT') {
    putInFlight++;
    return p.then((r) => new Promise((res) => setTimeout(() => res(r), 250)));
  }
  return p;
};

const sandbox = {
  document: documentStub,
  fetch: slowFetch,
  encodeURIComponent,
  JSON, console, setTimeout, clearTimeout, Promise, Date,
  window: { confirm: () => true },
};
vm.createContext(sandbox);

const html = await (await realFetch(BASE + '/')).text();
const script = html.match(/<script>([\s\S]*)<\/script>/)[1];

function assert(cond, msg) {
  if (!cond) { console.error('FAIL:', msg); process.exitCode = 1; }
  else console.log('PASS:', msg);
}

async function api(method, path, body) {
  const r = await realFetch(BASE + path, {
    method,
    headers: { 'content-type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  });
  return { status: r.status, data: await r.json() };
}

// ---- create the draft directly via API (version 1) ----
const created = await api('POST', '/api/articles', { title: '标题A', summary: '摘要A', body: '正文A' });
const aid = created.data.article.id;

// ---- boot page script (it loads the list immediately) ----
vm.runInContext(script, sandbox);
await st(150);

// ---- click 编辑 on the rendered card ----
const editBtn = ids['article-list'].find('button', '编辑');
assert(!!editBtn, '列表渲染出编辑按钮');
editBtn.click();
await st(150);
assert(ids['title'].value === '标题A' && ids['summary'].value === '摘要A' && ids['body'].value === '正文A',
  '进入编辑态，表单载入已保存内容');

// ---- first save: body edited to 第一段 ----
ids['body'].value = '第一段';
const beforePut = putInFlight;
ids['draft-form'].dispatch('submit', { preventDefault() {} });
await st(80);
assert(putInFlight === beforePut + 1, '第一个 PUT 请求已发出');
assert(ids['save-btn'].disabled === true, '保存进行中按钮禁用，禁止重复提交');

// ---- user keeps typing during the wait ----
ids['body'].value = '第一段\n\n第二段';
ids['title'].value = '  新标题  ';   // whitespace-trim rule must apply on NEXT save, not now
await st(250); // let the slowed PUT response process

// ---- assertions after first save ----
assert(ids['body'].value === '第一段\n\n第二段', '等待期间补写的正文（含空行）完整保留，未被旧值覆盖');
assert(ids['title'].value === '  新标题  ', '等待期间重填的标题按当前输入原样保留（不提前 trim）');
assert(ids['summary'].value === '摘要A', '等待期间未改动的摘要显示本次保存后的值');
assert(/未保存|尚未保存/.test(ids['status'].textContent) && /已保存/.test(ids['status'].textContent),
  '状态明确提示本次提交已保存、仍有未保存修改：『' + ids['status'].textContent + '』');
assert(ids['status'].className.includes('warn'), '未保存提示使用 warn 样式而非普通成功');

const after1 = await api('GET', '/api/articles/' + aid);
assert(after1.data.article.body === '第一段', '服务端已保存正文只有“第一段”');
assert(after1.data.article.title === '标题A', '服务端标题仍为本次提交保存的标题，未提前展示未提交修改');
assert(after1.data.article.version === 2, '服务端版本递增到 2');
assert(after1.data.article.id === aid, '文章标识不变');
const list1 = await api('GET', '/api/articles');
const la = list1.data.articles.find((a) => a.id === aid);
assert(la.title === '标题A' && la.summary === '摘要A', '列表只反映实际保存内容');

// ---- second save: both pending edits go up, same article, no false 409 ----
ids['draft-form'].dispatch('submit', { preventDefault() {} });
await st(400);
const after2 = await api('GET', '/api/articles/' + aid);
assert(after2.status === undefined || true, '');
assert(after2.data.article.body === '第一段\n\n第二段', '再次保存后两段正文一同成为已保存正文');
assert(after2.data.article.title === '新标题', '再次保存时标题沿用去除首尾空白规则');
assert(after2.data.article.version === 3, '第二次保存版本为 3，未被误报为版本冲突');
assert(after2.data.article.id === aid && after2.data.article.status === 'draft', '仍是同一篇草稿（id/status 不变）');
assert(ids['body'].value === '第一段\n\n第二段', '表单正文与已保存内容一致');
assert(ids['title'].value === '新标题', '未在等待期改动后，标题同步为规范值');
assert(/已保存/.test(ids['status'].textContent) && !/未保存|尚未保存/.test(ids['status'].textContent),
  '内容一致时显示普通保存成功，不残留未保存提示：『' + ids['status'].textContent + '』');

const list2 = await api('GET', '/api/articles');
assert(list2.data.articles.length === 1, '始终只有一篇文章，未产生重复记录');

// ---- third flow: clearing summary during flight is a valid edit ----
ids['summary'].value = '';
ids['draft-form'].dispatch('submit', { preventDefault() {} });
await st(80);
ids['body'].value = '第一段\n\n第二段\n\n第三段'; // also edit body in flight
await st(250);
assert(ids['summary'].value === '', '等待期间清空摘要被保留，不被旧摘要填回');
assert(ids['body'].value === '第一段\n\n第二段\n\n第三段', '等待期间追加正文（含空行）完整保留');
const srv3 = await api('GET', '/api/articles/' + aid);
assert(srv3.data.article.summary === '', '本次提交已把摘要清空保存');
assert(srv3.data.article.body === '第一段\n\n第二段', '服务端正文仍为上一版，等待期追加尚未保存');
assert(srv3.data.article.version === 4, '清空摘要的保存成功，版本 4');

process.exit(process.exitCode || 0);

