import vm from 'node:vm';
import { setTimeout as st } from 'node:timers/promises';
const { setTimeout: st } = require('node:timers/promises');

const BASE = 'http://127.0.0.1:8123';

class El {
  constructor(tag, id) {
    this.tagName = tag;
    this.id = id || '';
    this.children = [];
    this.value = '';
    this.textContent = '';
    this.className = '';
    this.type = '';
    this.disabled = false;
    this.hidden = false;
    this._listeners = {};
    this.classList = {
      _set: new Set(),
      add(c) { this._set.add(c); },
      remove(c) { this._set.delete(c); },
      contains(c) { return this._set.has(c); },
    };
  }
  appendChild(c) { this.children.push(c); return c; }
  addEventListener(type, fn) {
    (this._listeners[type] = this._listeners[type] || []).push(fn);
  }
  dispatch(type, ev) { (this._listeners[type] || []).forEach((fn) => fn(ev)); }
  click() { this.dispatch('click', {}); }
  focus() {}
  reset() {}
  set innerHTML(v) { if (v === '') this.children = []; }
  get innerHTML() { return ''; }
  querySelector() { return null; }
  // find first descendant by tag (and optional text)
  find(tag, text) {
    for (const c of this.children) {
      if ((!tag || c.tagName === tag) && (text === undefined || c.textContent === text)) return c;
      const d = c.find(tag, text);
      if (d) return d;
    }
    return null;
  }
  findAll(tag, out = []) {
    for (const c of this.children) {
      if (!tag || c.tagName === tag) out.push(c);
      c.findAll(tag, out);
    }
    return out;
  }
}

const ids = {};
['draft-form','title','summary','body','save-btn','cancel-btn','status','edit-banner',
 'conflict-box','article-list','empty-tip'].forEach((id) => { ids[id] = new El(id === 'draft-form' ? 'form' : 'div', id); });
const documentStub = {
  getElementById: (id) => ids[id] || (ids[id] = new El('div', id)),
  createElement: (tag) => new El(tag),
};

// Slow down PUT responses so we can reliably edit while a save is in flight.
const realFetch = fetch;
let putInFlight = 0;
const slowFetch = (url, opts) => {
  const p = realFetch(url, opts);
  if (opts && opts.method === 'PUT') {
    putInFlight++;
    return p.then((r) => new Promise((res) => setTimeout(() => res(r), 250)));
  }
  return p;
};

