assert(after2.data.article.body === '第一段\n\n第二段', '再次保存后两段正文一同成为已保存正文');
assert(after2.data.article.title === '新标题', '再次保存时标题沿用去除首尾空白规则');
assert(after2.data.article.version === 3, '第二次保存版本为 3，未被误报为版本冲突');
assert(after2.data.article.id === aid && after2.data.article.status === 'draft', '仍是同一篇草稿（id/status 不变）');
assert(ids['body'].value === '第一段\n\n第二段', '表单正文与已保存内容一致');
assert(ids['title'].value === '新标题', '未在等待期改动后，标题同步为规范值');
assert(/已保存/.test(ids['status'].textContent) && !/未保存|尚未保存/.test(ids['status'].textContent),
  '内容一致时显示普通保存成功，不残留未保存提示：『' + ids['status'].textContent + '』');

const list2 = await api('GET', '/api/articles');
assert(list2.data.articles.length === 1, '始终只有一篇文章，未产生重复记录');

// ---- third flow: clearing summary during flight is a valid edit ----
ids['summary'].value = '';
ids['draft-form'].dispatch('submit', { preventDefault() {} });
await st(80);
ids['body'].value = '第一段\n\n第二段\n\n第三段'; // also edit body in flight
await st(250);
assert(ids['summary'].value === '', '等待期间清空摘要被保留，不被旧摘要填回');
assert(ids['body'].value === '第一段\n\n第二段\n\n第三段', '等待期间追加正文（含空行）完整保留');
const srv3 = await api('GET', '/api/articles/' + aid);
assert(srv3.data.article.summary === '', '本次提交已把摘要清空保存');
assert(srv3.data.article.body === '第一段\n\n第二段', '服务端正文仍为上一版，等待期追加尚未保存');
assert(srv3.data.article.version === 4, '清空摘要的保存成功，版本 4');

