failNextPut=true;
ids['draft-form'].dispatch('submit',{preventDefault(){}});
await st(50);
ids['body'].value='提交的内容\n\n等待期间又写的';   // edit during the failing request
ids['summary'].value='等待期填写的摘要';
await st(250);
assert(ids['body'].value==='提交的内容\n\n等待期间又写的','失败时保留提交后的全部正文输入（含空行）');
assert(ids['summary'].value==='等待期填写的摘要','失败时保留提交后填写的摘要');
assert(/失败/.test(ids['status'].textContent) && ids['status'].className.includes('err'),
  '失败显示明确原因：『'+ids['status'].textContent+'』');
assert(ids['save-btn'].disabled===false && ids['save-btn'].textContent==='保存修改','失败后按钮恢复可再次保存');
failNextPut=false;

// ---- retry succeeds against same article, no false conflict ----
ids['draft-form'].dispatch('submit',{preventDefault(){}});
await st(300);
const srv=await api('GET','/api/articles/'+first.id);
assert(srv.data.article.body==='提交的内容\n\n等待期间又写的' && srv.data.article.summary==='等待期填写的摘要',
  '恢复后再次保存成功，全部输入写入同一篇草稿');
assert(ids['conflict-box'].hidden===true,'上一轮失败未误报版本冲突');

// ---- genuine 409 from another page: stale version rejected, form (incl. in-flight edits) kept ----
const baseVersion=srv.data.article.version;
// another client saves first
await api('PUT','/api/articles/'+first.id,{title:'标题A',summary:'',body:'另一页面保存的版本',version:baseVersion});
ids['body'].value='我这边要保存的内容';
ids['draft-form'].dispatch('submit',{preventDefault(){}});   // uses stale base version+1? no: editing.version is still baseVersion
await st(50);
ids['title'].value='标题A-冲突期间修改';
await st(250);
assert(/409|较新/.test(ids['status'].textContent),'真实冲突时明确提示 409 较新版本：『'+ids['status'].textContent+'』');
assert(ids['body'].value==='我这边要保存的内容','冲突后表单正文全部保留');
assert(ids['title'].value==='标题A-冲突期间修改','冲突期间提交后修改的标题同样保留');
assert(ids['conflict-box'].hidden===false,'冲突对照区展示双方内容');
assert(ids['conflict-box'].find('dd') || ids['conflict-box'].textContent.includes('另一页面保存的版本') ||
  JSON.stringify(ids['conflict-box']).includes('另一页面保存的版本'),'对照区含最新已保存版本');

// user explicitly discards and loads newest
const discardBtn=ids['conflict-box'].find('button','放弃当前输入并载入最新内容');
assert(!!discardBtn,'提供显式“放弃当前输入并载入最新内容”按钮');
discardBtn.click();
await st(200);
assert(ids['body'].value==='另一页面保存的版本','仅在用户明确选择后才载入最新版本');
assert(ids['title'].value==='标题A','载入最新版本后标题为已保存值');

process.exit(process.exitCode||0);

